INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6370461, 943985, 91783, '<td valign="top">it seems like this shot has really soft focus, or you did some funny editing. the eyes are the most important part of the portrait, they should be tack sharp. maybe try to focus a little bit more on that next time?<br/> <br/>I think that the colors are good and that her expression doesn''t seemed forced which is a good thing :) pretty model</td>', 'it seems like this shot has really soft focus, or you did some funny editing. the eyes are the most important part of the portrait, they should be tack sharp. maybe try to focus a little bit more on that next time? I think that the colors are good and that her expression doesn''t seemed forced which is a good thing :) pretty model', '2011-04-01 21:22:01.000000', NULL, 1),
(6370462, 943840, 75618, '<td valign="top">Very interesting abstraction! I wish the rails were perfectly vertical but that''s probably beyond your control. Wonderful vision overall. 8</td>', 'Very interesting abstraction! I wish the rails were perfectly vertical but that''s probably beyond your control. Wonderful vision overall. 8', '2011-04-01 21:24:09.000000', NULL, 1),
(6370463, 943925, 75618, '<td valign="top">Gorgeous! Wonderfully processed, love the muted tones.</td>', 'Gorgeous! Wonderfully processed, love the muted tones.', '2011-04-01 21:25:46.000000', NULL, 1),
(6370464, 943195, 91783, '<td valign="top">if this is a sp, you did a really good job with sharpness and clearity. But have a little bit more control of your face. You look confused a little, like, "what am i supposed to do?"<br/> <br/>I think you did a great job with your lighting :) nice and even!<br/> <br/>good luck from a fellow sp competitor :)</td>', 'if this is a sp, you did a really good job with sharpness and clearity. But have a little bit more control of your face. You look confused a little, like, "what am i supposed to do?" I think you did a great job with your lighting :) nice and even! good luck from a fellow sp competitor :)', '2011-04-01 21:25:58.000000', NULL, 1),
(6370466, 944023, 75618, '<td valign="top">This makes me feel like I''m floating. Wonderful tones, elegantly composed. 9</td>', 'This makes me feel like I''m floating. Wonderful tones, elegantly composed. 9', '2011-04-01 21:27:32.000000', NULL, 1),
(6370467, 943141, 91783, '<td valign="top">when you have something this simple and dramatic at the same time, watch out for distracting things. ex. the two black things in the bottom left corner. Just be aware of that.<br/> <br/>Colors are really good! nice job &amp; good luck :)</td>', 'when you have something this simple and dramatic at the same time, watch out for distracting things. ex. the two black things in the bottom left corner. Just be aware of that. Colors are really good! nice job & good luck :)', '2011-04-01 21:28:40.000000', NULL, 1),
(6370469, 943865, 75618, '<td valign="top">Love these grasses. I have hundreds of shots of them. Great bokeh and gradient. The bright spot is a little distracting though.</td>', 'Love these grasses. I have hundreds of shots of them. Great bokeh and gradient. The bright spot is a little distracting though.', '2011-04-01 21:30:07.000000', NULL, 1),
(6370470, 944013, 91783, '<td valign="top">kinda cute shoes... but i think that if your going to take pictures of some like that, put the subject on something more contrasting or complimentary to them.<br/> <br/>The shoes could be a little sharper but over all nice job with exposure.<br/> <br/>good luck :)</td>', 'kinda cute shoes... but i think that if your going to take pictures of some like that, put the subject on something more contrasting or complimentary to them. The shoes could be a little sharper but over all nice job with exposure. good luck :)', '2011-04-01 21:30:39.000000', NULL, 1),
(6370471, 941002, 91783, '<td valign="top">WHY?!?!?!?!?!?! Why is this SO dang small!!!! It looks like it could be such a great picture!  D'':<br/> <br/>i think the colors are great, and it seems like you got the focus right. but the picture size is So small! just dont resize it so much!<br/> <br/>:(</td>', 'WHY?!?!?!?!?!?! Why is this SO dang small!!!! It looks like it could be such a great picture!  D'': i think the colors are great, and it seems like you got the focus right. but the picture size is So small! just dont resize it so much! :(', '2011-04-01 21:32:41.000000', NULL, 1),
