INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6371117, 943006, 772, '<td valign="top">This is a great character portrait... very nicely executed and the black and white treatment adds a lot of feeling and texture to this image.  I''m a personal fan of this type of shot and yours is one of the best I have seen lately.  When presenting a shot like this to a DPC challenge, it''s important to find a way to connect the viewer to the image.  Even though I don''t know this person or have any link to him, this photo makes me want to know him.  Drawing in an unconnected viewer is hard to do, but I think you have done it well here... a definite 10 from me... nice work :)</td>', 'This is a great character portrait... very nicely executed and the black and white treatment adds a lot of feeling and texture to this image.  I''m a personal fan of this type of shot and yours is one of the best I have seen lately.  When presenting a shot like this to a DPC challenge, it''s important to find a way to connect the viewer to the image.  Even though I don''t know this person or have any link to him, this photo makes me want to know him.  Drawing in an unconnected viewer is hard to do, but I think you have done it well here... a definite 10 from me... nice work :)', '2011-04-02 21:09:39.000000', NULL, 1),
(6371118, 939400, 772, '<td valign="top">I love this image and I hope others in this competition can take a moment to explore it as much as I have.  It''s fantastic in more ways than I can really put into words myself.  I have come back to look at this image several times and I see something new and/or different each time I look.  This might possibly be my personal favorite of this challenge... Great work :)</td>', 'I love this image and I hope others in this competition can take a moment to explore it as much as I have.  It''s fantastic in more ways than I can really put into words myself.  I have come back to look at this image several times and I see something new and/or different each time I look.  This might possibly be my personal favorite of this challenge... Great work :)', '2011-04-02 21:12:48.000000', NULL, 1),
(6371124, 940703, 39057, '<td valign="top">LOL....I really like this but IMO it will finish in the bottom 25%. At times I don''t think voters care about anything except the candy. I could be wrong though !  8 from me.</td>', 'LOL....I really like this but IMO it will finish in the bottom 25%. At times I don''t think voters care about anything except the candy. I could be wrong though !  8 from me.', '2011-04-02 21:36:02.000000', NULL, 1),
(6371127, 942349, 31889, '<td valign="top">This looks like an interesting capture and could''ve made for a nice image but the processing here did little to enhance the submission and I''m guessing will be hurting your score.</td>', 'This looks like an interesting capture and could''ve made for a nice image but the processing here did little to enhance the submission and I''m guessing will be hurting your score.', '2011-04-02 22:05:34.000000', NULL, 1),
(6371129, 939559, 31889, '<td valign="top">I think you have a very good chance of picking up a posthumous award but as a general rule these type of images will not score well here at DPC.  I assume you knew that before submitting though.</td>', 'I think you have a very good chance of picking up a posthumous award but as a general rule these type of images will not score well here at DPC.  I assume you knew that before submitting though.', '2011-04-02 22:07:01.000000', NULL, 1),
(6371130, 943987, 31889, '<td valign="top">I could imagine this image being displayed as a piece of wall art or in a coffee book but unfortunately it''s way off the mark for this place. If you are here to seriously compete in the challenges then it''s best to avoid submitting these more abstract types of work.</td>', 'I could imagine this image being displayed as a piece of wall art or in a coffee book but unfortunately it''s way off the mark for this place. If you are here to seriously compete in the challenges then it''s best to avoid submitting these more abstract types of work.', '2011-04-02 22:12:12.000000', NULL, 1),
(6371133, 943306, 31889, '<td valign="top">Reminds me a bit of Jackos infamous attempt at a brown ribbon.  The framing is good, (even though I hate cat images), but what ever processing you did to the image resulted in a most DPC unfriendly image which will no doubt hurst your score here.</td>', 'Reminds me a bit of Jackos infamous attempt at a brown ribbon.  The framing is good, (even though I hate cat images), but what ever processing you did to the image resulted in a most DPC unfriendly image which will no doubt hurst your score here.', '2011-04-02 22:14:22.000000', NULL, 1),
