(6375167, 943473, 114225, '<td valign="top">Great details and I really enjoy the tilted subject to get as much of it in frame as possible.</td>', 'Great details and I really enjoy the tilted subject to get as much of it in frame as possible.', '2011-04-05 15:55:31.000000', NULL, 1),
(6375169, 943084, 114225, '<td valign="top">I really like the details you captured, but am not a fan of the selective desaturation here. It takes a beautiful natural scene and gives it a fake feel.</td>', 'I really like the details you captured, but am not a fan of the selective desaturation here. It takes a beautiful natural scene and gives it a fake feel.', '2011-04-05 15:56:24.000000', NULL, 1),
(6375170, 943334, 114225, '<td valign="top">Beautiful setting. The green moss on the rocks really stands out. It may just be me, but this feels like it could use a bit more contrast; there are no deep blacks or bright whites.</td>', 'Beautiful setting. The green moss on the rocks really stands out. It may just be me, but this feels like it could use a bit more contrast; there are no deep blacks or bright whites.', '2011-04-05 15:57:42.000000', NULL, 1),
(6375173, 943985, 114225, '<td valign="top">While the blowing of the hair adds a bit of uniqueness, for me, I really need to see the models eyes to connect. For this shot, one eye is completely covered, and the other partially, which is blocking that connection.</td>', 'While the blowing of the hair adds a bit of uniqueness, for me, I really need to see the models eyes to connect. For this shot, one eye is completely covered, and the other partially, which is blocking that connection.', '2011-04-05 15:58:55.000000', NULL, 1),
(6375174, 943320, 114225, '<td valign="top">Wonderful details. Leave it up to nature to create a perfect color palette.</td>', 'Wonderful details. Leave it up to nature to create a perfect color palette.', '2011-04-05 16:00:13.000000', NULL, 1),
(6375175, 943932, 114225, '<td valign="top">I see what you were going for with the background light placement, but for me, it''s a distraction. I think maybe that is because of the very heavy vignette which is exactly the opposite of the bright white light.</td>', 'I see what you were going for with the background light placement, but for me, it''s a distraction. I think maybe that is because of the very heavy vignette which is exactly the opposite of the bright white light.', '2011-04-05 16:01:28.000000', NULL, 1),
(6375177, 944037, 114225, '<td valign="top">Great tones and feeling to this image. I can practically smell the farm air.</td>', 'Great tones and feeling to this image. I can practically smell the farm air.', '2011-04-05 16:05:31.000000', NULL, 1),
(6375178, 941002, 114225, '<td valign="top">I''m sure you have heard this already, but you have a beautiful scene, why make is so darn small?</td>', 'I''m sure you have heard this already, but you have a beautiful scene, why make is so darn small?', '2011-04-05 16:06:22.000000', NULL, 1),
(6375185, 942395, 114225, '<td valign="top">Lovely scene, perfectly executed.</td>', 'Lovely scene, perfectly executed.', '2011-04-05 16:14:46.000000', NULL, 1),
