(6375188, 943176, 114225, '<td valign="top">Wonderful vantage point. I imagine this is infrared? If so, it''s one of the better infrared examples I have seen.</td>', 'Wonderful vantage point. I imagine this is infrared? If so, it''s one of the better infrared examples I have seen.', '2011-04-05 16:17:25.000000', NULL, 1),
(6375190, 943988, 114225, '<td valign="top">Simply splendid scene with great vivid colors and the little snow caps are just amazing.</td>', 'Simply splendid scene with great vivid colors and the little snow caps are just amazing.', '2011-04-05 16:19:15.000000', NULL, 1),
(6375193, 943390, 114225, '<td valign="top">Great view, but I fear that the processing really hurt this image. Notice the little black and white specks all over the rocks? Those artifacts are likely due to over-sharpening.</td>', 'Great view, but I fear that the processing really hurt this image. Notice the little black and white specks all over the rocks? Those artifacts are likely due to over-sharpening.', '2011-04-05 16:23:04.000000', NULL, 1),
(6375234, 943050, 86218, '<td valign="top">Lovely image - well done. Recognize this immediately.</td>', 'Lovely image - well done. Recognize this immediately.', '2011-04-05 17:04:48.000000', NULL, 1),
