(6375262, 944007, 30712, '<td valign="top">I love the formality of this image which looks like a repeating pattern but on closer inspection you can see that it contains so much variety.  It really is a joy to look at again and again.</td>', 'I love the formality of this image which looks like a repeating pattern but on closer inspection you can see that it contains so much variety.  It really is a joy to look at again and again.', '2011-04-05 17:44:17.000000', NULL, 1),
(6375301, 943602, 108069, '<td valign="top">Wonderful colors and lines into the depths of the photo. Shimmering, glowing, with some stars for good measure. Outstanding photo.</td>', 'Wonderful colors and lines into the depths of the photo. Shimmering, glowing, with some stars for good measure. Outstanding photo.', '2011-04-05 18:38:09.000000', NULL, 1),
