INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6375763, 942337, 30861, '<td valign="top">Water drops with a difference. There''s an add, distracting sort of emotional quotient to this one. Well done!</td>', 'Water drops with a difference. There''s an add, distracting sort of emotional quotient to this one. Well done!', '2011-04-06 00:33:32.000000', NULL, 1),
(6376121, 943681, 121789, '<td valign="top">Nice silhouette - I like the way the light appears to come from the pilot and expand up into and beyond the canopy - well done! 8</td>', 'Nice silhouette - I like the way the light appears to come from the pilot and expand up into and beyond the canopy - well done! 8', '2011-04-06 04:31:51.000000', NULL, 1),
(6376162, 942806, 108069, '<td valign="top">Really nice complimentary color balance with the blue and orange. Silhouettes are always cool. Fun shot.</td>', 'Really nice complimentary color balance with the blue and orange. Silhouettes are always cool. Fun shot.', '2011-04-06 05:37:34.000000', NULL, 1),
(6376181, 939896, 108069, '<td valign="top">Great photo. I love these tones, and the texture and detail in the dock is really rich. The motion-blurred clouds are a bit of a distraction, but on the other hand it''s an interesting contrast with the super sharp lakefront scene on the other side. Nice stuff.<br/> <br/>Another interesting crop for you would be a pano-type crop (maybe about 3 x 1?) that would put the lakefront horizon at the top third of the image. This would make that wonderful dock even more prevalent, as well as the interesting other side of the lake. It wouldn''t have worked here on DPC though with the presentation size limitations.</td>', 'Great photo. I love these tones, and the texture and detail in the dock is really rich. The motion-blurred clouds are a bit of a distraction, but on the other hand it''s an interesting contrast with the super sharp lakefront scene on the other side. Nice stuff. Another interesting crop for you would be a pano-type crop (maybe about 3 x 1?) that would put the lakefront horizon at the top third of the image. This would make that wonderful dock even more prevalent, as well as the interesting other side of the lake. It wouldn''t have worked here on DPC though with the presentation size limitations.', '2011-04-06 06:52:15.000000', NULL, 1),
(6376184, 942412, 108069, '<td valign="top">Sweet stuff. Great lines, wonderful crisp detail in the pavement and trees, and some nice silvery tones in the sky. Interesting contrast galore. My kind of shot.</td>', 'Sweet stuff. Great lines, wonderful crisp detail in the pavement and trees, and some nice silvery tones in the sky. Interesting contrast galore. My kind of shot.', '2011-04-06 06:56:11.000000', NULL, 1),
(6376189, 943210, 108069, '<td valign="top">He was certainly the master of suspense, but he never displayed this much grace. Well, maybe in his dreams. This is quite a beautiful shot. The unbearable lightness of contrast and tones.</td>', 'He was certainly the master of suspense, but he never displayed this much grace. Well, maybe in his dreams. This is quite a beautiful shot. The unbearable lightness of contrast and tones.', '2011-04-06 07:12:37.000000', NULL, 1),
(6376256, 943491, 119419, '<td valign="top">See she looks better without the gas mask ;)</td>', 'See she looks better without the gas mask ;)', '2011-04-06 09:06:44.000000', NULL, 1),
(6376269, 944003, 20799, '<td valign="top">Good remake of this idea. Maybe it''s the other photo I''ve seen, that makes me  think that the area surrounding the frame should be warmer. Also the DOF, maybe the trees make it a little busy. But overall I like it a lot.</td>', 'Good remake of this idea. Maybe it''s the other photo I''ve seen, that makes me  think that the area surrounding the frame should be warmer. Also the DOF, maybe the trees make it a little busy. But overall I like it a lot.', '2011-04-06 09:40:27.000000', NULL, 1),
(6376270, 943988, 20799, '<td valign="top">A wonderful <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=54446" rel="nofollow" target="_blank">hahn23</a>-style landscape. Very well balanced imo, love the colors. Fantastic, the scene, the execution and pp.</td>', 'A wonderful  hahn23-style landscape. Very well balanced imo, love the colors. Fantastic, the scene, the execution and pp.', '2011-04-06 09:42:53.000000', NULL, 1),
(6376271, 943021, 108069, '<td valign="top">I think this could be used as instructional material on composition. The smooth flow pulls our eyes down the falls and then they circle back up that rock path into the rest of the picture to arrive at the pinnacle. Rinse. Repeat. It''s quite amazing. Very well done.</td>', 'I think this could be used as instructional material on composition. The smooth flow pulls our eyes down the falls and then they circle back up that rock path into the rest of the picture to arrive at the pinnacle. Rinse. Repeat. It''s quite amazing. Very well done.', '2011-04-06 09:44:24.000000', NULL, 1),
(6376288, 943404, 20799, '<td valign="top">The moment indeed! How was this taken, I want to know. Great shot.</td>', 'The moment indeed! How was this taken, I want to know. Great shot.', '2011-04-06 10:00:56.000000', NULL, 1),
(6376317, 942560, 63218, '<td valign="top">Low light, but good color. Nice lack of noise. Good detail. Interesting crop. And it does look delicious, I agree!</td>', 'Low light, but good color. Nice lack of noise. Good detail. Interesting crop. And it does look delicious, I agree!', '2011-04-06 10:28:16.000000', NULL, 1),
(6376345, 939400, 108069, '<td valign="top">The range of tone and texture is so abstract, so seamless and flowing without tethers that it should be unexplainable, and yet it''s entirely obvious and grounded in reality. Fantastic image.</td>', 'The range of tone and texture is so abstract, so seamless and flowing without tethers that it should be unexplainable, and yet it''s entirely obvious and grounded in reality. Fantastic image.', '2011-04-06 10:45:17.000000', NULL, 1),
(6376346, 943988, 108069, '<td valign="top">I dream of this location and these shooting conditions and you''ve executed it perfectly. Beautiful shot.</td>', 'I dream of this location and these shooting conditions and you''ve executed it perfectly. Beautiful shot.', '2011-04-06 10:50:43.000000', NULL, 1),
(6376347, 943871, 108069, '<td valign="top">Nice. Now if you can race back there for the cool colors challenge you''ll have a winner. This is beautiful. Great use of a leading line, great texture, lovely tones and colors. Well done.</td>', 'Nice. Now if you can race back there for the cool colors challenge you''ll have a winner. This is beautiful. Great use of a leading line, great texture, lovely tones and colors. Well done.', '2011-04-06 10:52:24.000000', NULL, 1),
