(6378017, 943792, 30982, '<td valign="top">Love the way his smile reaches all the way to his eyes.  A great face!</td>', 'Love the way his smile reaches all the way to his eyes.  A great face!', '2011-04-07 19:45:22.000000', NULL, 1),
(6378018, 939400, 30982, '<td valign="top">This is, simply, sublime.</td>', 'This is, simply, sublime.', '2011-04-07 19:45:34.000000', NULL, 1),
(6378019, 942917, 30982, '<td valign="top">I LOVE how they''re so evenly spaced!  Begs all sorts of questions.  Why are they on the road?  They have no riders... where are they going?  Love the soft hues, too.  This is just so very fun!<br/><br/><i>Message edited by author 2011-04-08 00:21:42.</i></td>', 'I LOVE how they''re so evenly spaced!  Begs all sorts of questions.  Why are they on the road?  They have no riders... where are they going?  Love the soft hues, too.  This is just so very fun!', '2011-04-07 19:46:14.000000', '2011-04-08 01:21:42.000000', 1),
(6378021, 941698, 70896, '<td valign="top">Love the tone, but that pedal getting cut on the bottom just kills me.... such a small detail. Still, the color and the texture is great!</td>', 'Love the tone, but that pedal getting cut on the bottom just kills me.... such a small detail. Still, the color and the texture is great!', '2011-04-07 19:46:44.000000', NULL, 1),
